    "content": "} func (s *APIV1Service) CreateMemo(ctx context.Context, request *v1pb.CreateMemoRequest) (*v1pb.Memo, error) { user, err := s.fetchCurrentUser(ctx) if err != nil { return nil, status.Errorf(codes.Internal, \"failed to get user\") } if user == nil { return nil, status.Errorf(codes.Unauthenticated, \"user not authenticated\") } memoUID, err := ValidateAndGenerateUID(request.MemoId) if err != nil { return nil, err } create := &store.Memo{ UID:        memoUID, CreatorID:  user.ID, Content:    request.Memo.Content, Visibility: convertVisibilityToStore(request.Memo.Visibility), } // Set custom timestamps if provided in the request. if request.Memo.CreateTime != nil && request.Memo.CreateTime.IsValid() { createdTs := request.Memo.CreateTime.AsTime().Unix() create.CreatedTs = createdTs } if request.Memo.UpdateTime != nil && request.Memo.UpdateTime.IsValid() { updatedTs := request.Memo.UpdateTime.AsTime().Unix() create.UpdatedTs = updatedTs } contentLengthLimit, err := s.getContentLengthLimit(ctx) if err != nil { return nil, status.Errorf(codes.Internal, \"failed to get content length limit\") } if len(create.Content) > contentLengthLimit { return nil, status.Errorf(codes.InvalidArgument, \"content too long (max %d characters)\", contentLengthLimit) } if err := memopayload.RebuildMemoPayload(ctx, create, s.MarkdownService); err != nil { return nil, status.Errorf(codes.Internal, \"failed to rebuild memo payload: %v\", err) } if request.Memo.Location != nil { create.Payload.Location = convertLocationToStore(request.Memo.Location) } memo, err := s.Store.CreateMemo(ctx, create) if err != nil { // Check for unique constraint violation (AIP-133 compliance) errMsg := err.Error() if strings.Contains(errMsg, \"UNIQUE constraint failed\") || strings.Contains(errMsg, \"duplicate key\") || strings.Contains(errMsg, \"Duplicate entry\") { return nil, status.Errorf(codes.AlreadyExists, \"memo with ID %q already exists\", memoUID) } return nil, err } attachments := []*store.Attachment{} if len(request.Memo.Attachments) > 0 { if err := s.setMemoAttachmentsInternal(ctx, user, memo, request.Memo.Attachments); err != nil { return nil, errors.Wrap(err, \"failed to set memo attachments\") } a, err := s.Store.ListAttachments(ctx, &store.FindAttachment{ MemoID: &memo.ID, }) if err != nil { return nil, errors.Wrap(err, \"failed to get memo attachments\") } attachments = a } if len(request.Memo.Relations) > 0 { if err := s.setMemoRelationsInternal(ctx, memo, request.Memo.Relations); err != nil { return nil, errors.Wrap(err, \"failed to set memo relations\") } } relations, err := s.loadMemoRelations(ctx, memo) if err != nil { return nil, errors.Wrap(err, \"failed to load memo relations\") } memoMessage, err := s.convertMemoFromStore(ctx, memo, nil, attachments, relations) if err != nil { return nil, errors.Wrap(err, \"failed to convert memo\") } // Try to dispatch webhook when memo is created. if err := s.DispatchMemoCreatedWebhook(ctx, memoMessage); err != nil { slog.Warn(\"Failed to dispatch memo created webhook\", slog.Any(\"err\", err)) } // Broadcast live refresh event (skipped when called from CreateMemoComment). if !isSSESuppressed(ctx) { s.SSEHub.Broadcast(&SSEEvent{ Type:       SSEEventMemoCreated, Name:       memoMessage.Name, Visibility: memo.Visibility, CreatorID:  resolveSSECreatorID(memo, nil), }) } if !isMentionNotificationSuppressed(ctx) { s.dispatchMemoMentionNotificationsBestEffort(ctx, memo, nil, \"\") } return memoMessage, nil } func (s *APIV1Service) ListMemos(ctx context.Context, request *v1pb.ListMemosRequest) (*v1pb.ListMemosResponse, error) {"
